163	\begin{definition}[Line-point distributions]\label{def:line-point-dist}
164		% A line description retains the seed used to select its coordinate.
165		\lean{MIPStarRE.QPBT.aLinePointDist, MIPStarRE.QPBT.dLinePointDist}
166		\lean{MIPStarRE.QPBT.linePointDist}
167		\lean{MIPStarRE.QPBT.aLinePointDist_isProbability}
